pragma solidity ^0.8.20;

contract Crowdfunding {
    uint public fundingGoal;
    uint public deadline;
    address payable public owner;
    mapping(address => bool) public contributors;

    event GoalReached();
    event RefundRequested(address indexed contributor);
    event RefundSent(address indexed contributor);

    constructor(uint _fundingGoal, uint _deadline) {
        fundingGoal = _fundingGoal * 1 ether; // convert to wei
        deadline = block.timestamp + _deadline;
        owner = msg.sender;
    }

    function contribute() public payable {
        require(msg.value > 0, "Contribution amount must be greater than zero");
        require(block.timestamp < deadline, "Crowdfunding has ended");
        require(contributors[msg.sender] == false, "You have already contributed");

        contributors[msg.sender] = true;
    }

    function endCrowdfunding() public {
        require(msg.sender == owner, "Only the owner can withdraw funds");
        require(block.timestamp >= deadline, "Crowdfunding has not ended yet");
        require(address(this).balance >= fundingGoal, "Funding goal not met");

        emit GoalReached();
        owner.transfer(address(this).balance);
    }

    function refund() public {
        require(msg.sender != owner, "The owner cannot request a refund");
        require(block.timestamp < deadline, "Crowdfunding has ended");
        require(contributors[msg.sender] == true, "You have not contributed to this campaign");

        emit RefundRequested(msg.sender);
        uint amount = msg.value;
        if (address(this).balance >= fundingGoal) {
            owner.transfer(amount);
        } else {
            contributors[msg.sender] = false;
        }
    }

    function refundSent() public view returns(bool) {
        return contributors[msg.sender];
    }
}
