contract VotingContract {
    struct Proposal {
        string description;
        uint voteCount;
    }

    Proposal[] public proposals;
    address[] public voters;

    mapping (string => uint) public proposalIdToIndex;

    function getProposal(uint index) public view returns(string memory, uint voteCount) {
        return (proposals[index].description, proposals[index].voteCount);
    }

    function addProposal(string memory description) public {
        require(bytes(description).length > 0, "Description must be non-empty");

        proposalIdToIndex[description] = proposals.length;
        proposals.push(Proposal({description: description, voteCount: 0}));
    }

    function vote(string memory description) public {
        uint index = proposalIdToIndex[description];
        require(index != 0, "Description does not exist");

        Proposal storage proposal = proposals[index];

        require(voters.indexOf(msg.sender) == -1, "You have already voted");

        voters.push(msg.sender);
        proposal.voteCount += 1;
    }
}
