contract Vesting {
    address public beneficiary;
    uint256 public cliff;
    uint256 public duration;
    uint256 public amount;

    bool public vested;

    constructor(address _beneficiary, uint256 _cliff, uint256 _duration) {
        beneficiary = _beneficiary;
        cliff = block.timestamp + _cliff;
        duration = _duration;
        vested = false;
    }

    function vest() public {
        require(!vested, "already_vested");
        require(block.timestamp >= cliff, "cliff_not_passed");

        uint256 timePassed = block.timestamp - cliff;
        uint256 amountToVest = (timePassed * amount) / duration;

        if (amountToVest > 0) {
            payable(beneficiary).transfer(amountToVest);
            vested = true;
        }
    }
}
